class Solution {
public:
    int findMaxConsecutiveOnes(vector<int>& nums) {
        int left = 0, zeros = 0, best = 0;
        for (int right = 0; right < static_cast<int>(nums.size()); ++right) {
            zeros += nums[right] == 0;
            while (zeros > 1) {
                zeros -= nums[left++] == 0;
            }
            best = max(best, right - left + 1);
        }
        return best;
    }
};
